import subprocess, sys
B="/workspace/dataset/test15_executable"
def run(W):
    p=subprocess.run([B,W],capture_output=True)
    return p.returncode,p.stdout,p.stderr
def demod(W):
    # returns (crashed, resultbytes_or_None, stderr)
    rc,so,se=run(W)
    lines=so.split(b"\n")
    if rc==0:
        # lines: plural, camel, isPlural, isSingular, demod, ''
        return False, lines[4], se
    return True, None, se

# spec model
def spec(W):
    s=b"Module::"+W
    pos=s.rfind(b":")
    start=(1 if pos==-1 else pos+2)
    if start>len(s):
        return ("CRASH", start, len(s))
    return ("OK", s[start:])

def check(W):
    crashed,res,se=demod(W)
    pred=spec(W)
    if crashed:
        act=("CRASH",)+tuple(int(x) for x in __import__("re").findall(rb"which is (\d+)",se))
    else:
        act=("OK",res)
    ok = (act==pred)
    return ok,act,pred,se

if __name__=="__main__":
    pass
