use strict; use warnings;
my $B="/workspace/dataset/test15_executable";
sub run_bin {
  my ($W)=@_;
  my $so_f="/tmp/_so.$$"; my $se_f="/tmp/_se.$$";
  my $pid=fork(); 
  if(!$pid){ open(STDOUT,'>',$so_f); open(STDERR,'>',$se_f); exec($B,$W) or exit(127); }
  waitpid($pid,0); my $st=$?;
  local $/; open(my $h,'<',$so_f); binmode $h; my $so=<$h>||''; close $h;
  open(my $h2,'<',$se_f); binmode $h2; my $se=<$h2>||''; close $h2;
  unlink $so_f,$se_f;
  my $rc = ($st & 127) ? 128+($st&127) : ($st>>8);
  return ($rc,$so,$se);
}
# observed demodulize
sub obs {
  my ($W)=@_;
  my ($rc,$so,$se)=run_bin($W);
  if($rc==0){
    my @L=split(/\n/,$so,-1);
    return ("OK",$L[4],$rc,$se);
  } else {
    my @n = ($se =~ /which is (\d+)/g);
    return ("CRASH",join(",",@n),$rc,$se);
  }
}
# spec model
sub spec {
  my ($W)=@_;
  my $s="Module::".$W;
  my $pos=rindex($s,":");
  my $start = ($pos<0) ? 1 : $pos+2;
  if($start > length($s)){ return ("CRASH", ($start).",".length($s)); }
  return ("OK", substr($s,$start));
}
sub hx { my $x=shift; return join(' ', map { sprintf("%02x",ord) } split //,$x); }
sub check {
  my ($W,$label)=@_;
  my ($ak,$av,$rc,$se)=obs($W);
  my ($pk,$pv)=spec($W);
  my $ok = ($ak eq $pk && $av eq $pv);
  printf("%s %-22s W=[%s] act=%s(%s) pred=%s(%s)\n",
     ($ok?"PASS":"**FAIL**"), ($label//''), hx($W), $ak, ($ak eq 'OK'?hx($av):$av), $pk, ($pk eq 'OK'?hx($pv):$pv)) unless ($ok && ($ENV{QUIET}//'') eq '1');
  return $ok;
}
